"use client";

import {
  Conversation,
  ConversationContent,
  ConversationEmptyState,
  ConversationScrollButton,
} from "@repo/design-system/components/ai-elements/conversation";
import {
  Message,
  MessageContent,
  MessageResponse,
} from "@repo/design-system/components/ai-elements/message";
import {
  PromptInput,
  PromptInputBody,
  PromptInputFooter,
  PromptInputSubmit,
  PromptInputTextarea,
} from "@repo/design-system/components/ai-elements/prompt-input";
import {
  Reasoning,
  ReasoningContent,
  ReasoningTrigger,
} from "@repo/design-system/components/ai-elements/reasoning";
import { Shimmer } from "@repo/design-system/components/ai-elements/shimmer";
import {
  Tool,
  ToolContent,
  ToolHeader,
  ToolInput,
  ToolOutput,
} from "@repo/design-system/components/ai-elements/tool";
import { useEveAgent } from "eve/react";
import { BrainIcon } from "lucide-react";
import { useCallback, useMemo } from "react";
import { type CitedFact, FactCitation } from "./fact-citation";
import { type CitedSource, SourceCitation } from "./source-citation";

// The model emits <fact id="…"/> and <source id="…"/> inline. Streamdown
// strips unknown tags by default, so each tag and its one attribute have to
// be allow-listed explicitly — which also means nothing else the model
// invents can reach the DOM.
const ALLOWED_TAGS = { fact: ["id"], source: ["id"] };

interface ToolPart {
  errorText?: string;
  input?: unknown;
  output?: unknown;
  state?: string;
  type: string;
}

const isSearchTool = (part: { type: string }) =>
  part.type === "tool-search-knowledge" ||
  part.type === "dynamic-tool" ||
  part.type.startsWith("tool-");

/**
 * eve delivers tool results in the AI SDK result envelope
 * `{ type: "json" | "error-text" | …, value }`, so the payload lives one
 * level down. Unwrap defensively — a bare payload passes through untouched.
 */
const unwrapToolOutput = (
  output: unknown
): { errorText?: string; value?: unknown } => {
  if (output === null || typeof output !== "object") {
    return { value: output };
  }
  const { type, value } = output as { type?: unknown; value?: unknown };
  if (type === "error-text" || type === "error-json") {
    return {
      errorText: typeof value === "string" ? value : JSON.stringify(value),
    };
  }
  if (type === "json" || type === "text" || type === "content") {
    return { value };
  }
  return { value: output };
};

/**
 * Collect everything the agent has retrieved so far — confirmed facts and raw
 * sources. Citations resolve against tool output, never against the prose:
 * the model can only cite what the knowledge base actually handed it.
 */
const ingestToolOutput = (
  raw: unknown,
  facts: Map<string, CitedFact>,
  sources: Map<string, CitedSource>
) => {
  const output = unwrapToolOutput(raw).value as
    | { facts?: CitedFact[]; sources?: CitedSource[] }
    | undefined;
  for (const fact of output?.facts ?? []) {
    if (fact?.id) {
      facts.set(fact.id, fact);
    }
  }
  for (const source of output?.sources ?? []) {
    if (source?.id) {
      sources.set(source.id, source);
    }
  }
};

const collectCitables = (
  messages: { parts: { output?: unknown; type: string }[] }[]
): { facts: Map<string, CitedFact>; sources: Map<string, CitedSource> } => {
  const facts = new Map<string, CitedFact>();
  const sources = new Map<string, CitedSource>();
  for (const message of messages) {
    for (const part of message.parts) {
      if (isSearchTool(part)) {
        ingestToolOutput(part.output, facts, sources);
      }
    }
  }
  return { facts, sources };
};

const thinkingMessage = (isStreaming: boolean, duration?: number) => {
  if (isStreaming || duration === 0) {
    return <Shimmer duration={1}>Denkt nach …</Shimmer>;
  }
  if (duration === undefined) {
    return <p>Kurz nachgedacht</p>;
  }
  return <p>{duration}s nachgedacht</p>;
};

export const KnowledgeChat = () => {
  const agent = useEveAgent();
  const isBusy = agent.status === "submitted" || agent.status === "streaming";

  // Covers the gap between sending and the first streamed part — once the
  // assistant's reasoning starts arriving, its own "Denkt nach …" takes over.
  const lastMessage = agent.data.messages.at(-1) as
    | { parts: unknown[]; role?: string }
    | undefined;
  const awaitingResponse =
    isBusy &&
    (lastMessage?.role !== "assistant" || lastMessage.parts.length === 0);

  const { facts, sources } = useMemo(
    () => collectCitables(agent.data.messages as never),
    [agent.data.messages]
  );

  const components = useMemo(
    () => ({
      fact: ({ id }: { id?: string }) => <FactCitation facts={facts} id={id} />,
      source: ({ id }: { id?: string }) => (
        <SourceCitation id={id} sources={sources} />
      ),
    }),
    [facts, sources]
  );

  // PromptInput owns the textarea and hands back the composed message, so the
  // composer state lives there rather than being mirrored here.
  const submit = useCallback(
    (message: { text?: string }) => {
      const text = message.text?.trim() ?? "";
      if (text.length === 0 || isBusy) {
        return;
      }
      // Rejections surface through agent.error, which the view renders; this
      // catch only keeps the promise from floating.
      // eve 0.31.0 made send() positional: send(message, options) instead of
      // send({ message }).
      agent.send(text).catch(() => undefined);
    },
    [agent, isBusy]
  );

  return (
    <div className="mx-auto flex h-full w-full min-w-0 max-w-3xl flex-col gap-3">
      <Conversation className="min-h-0 flex-1 rounded-xl border">
        <ConversationContent
          // Center the empty state in the frame; harmless with messages
          // present, but overflowing content must not be justify-centered or
          // its top becomes unreachable.
          className={
            agent.data.messages.length === 0
              ? "min-h-full justify-center"
              : undefined
          }
        >
          {agent.data.messages.length === 0 ? (
            <ConversationEmptyState
              description="Jede Antwort zitiert die Fakten, auf denen sie beruht."
              icon={<BrainIcon className="size-8" />}
              title="Frag das Firmengedächtnis"
            />
          ) : null}

          {agent.data.messages.map((message) => (
            <Message from={message.role} key={message.id}>
              <MessageContent>
                {message.parts.map((part, index) => {
                  if (part.type === "reasoning") {
                    const reasoning = part as { state?: string; text?: string };
                    return (
                      <Reasoning
                        className="w-full"
                        isStreaming={reasoning.state === "streaming"}
                        // biome-ignore lint/suspicious/noArrayIndexKey: stream parts have no stable id and are append-only
                        key={index}
                      >
                        <ReasoningTrigger
                          getThinkingMessage={thinkingMessage}
                        />
                        <ReasoningContent>
                          {reasoning.text ?? ""}
                        </ReasoningContent>
                      </Reasoning>
                    );
                  }

                  if (part.type === "text") {
                    return (
                      <MessageResponse
                        allowedTags={ALLOWED_TAGS}
                        components={components}
                        // biome-ignore lint/suspicious/noArrayIndexKey: stream parts have no stable id and are append-only
                        key={index}
                      >
                        {part.text}
                      </MessageResponse>
                    );
                  }

                  if (isSearchTool(part)) {
                    const tool = part as ToolPart;
                    const { errorText, value } = unwrapToolOutput(tool.output);
                    return (
                      <Tool
                        // Fixed width: inside the fit-content message column
                        // a percentage width would grow with every streamed
                        // line of prose beneath it.
                        className="w-96 max-w-full"
                        // biome-ignore lint/suspicious/noArrayIndexKey: see above
                        key={index}
                      >
                        <ToolHeader
                          state={tool.state as never}
                          type={tool.type as never}
                        />
                        <ToolContent>
                          <ToolInput input={tool.input} />
                          <ToolOutput
                            errorText={tool.errorText ?? errorText}
                            output={value as never}
                          />
                        </ToolContent>
                      </Tool>
                    );
                  }

                  return null;
                })}
              </MessageContent>
            </Message>
          ))}

          {awaitingResponse ? (
            <Shimmer className="text-sm" duration={1.5}>
              Einen Moment …
            </Shimmer>
          ) : null}
        </ConversationContent>
        <ConversationScrollButton />
      </Conversation>

      {agent.error ? (
        <p className="text-destructive text-sm">{agent.error.message}</p>
      ) : null}

      {/* Match the conversation frame's radius on the composer's InputGroup,
          which PromptInput renders internally. */}
      <PromptInput
        className="[&>[data-slot=input-group]]:rounded-xl"
        onSubmit={submit}
      >
        <PromptInputBody>
          <PromptInputTextarea
            className="min-h-0"
            disabled={isBusy}
            placeholder="Was möchtest du wissen?"
          />
        </PromptInputBody>
        <PromptInputFooter className="justify-end">
          <PromptInputSubmit disabled={isBusy} status={agent.status} />
        </PromptInputFooter>
      </PromptInput>
    </div>
  );
};

"use client";

import { cn } from "@repo/design-system/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useCallback, useState } from "react";

/**
 * The signature element: the answer you get two minutes before a call, with
 * receipts you can open.
 *
 * The labels are deliberately not the ones the database uses. Nobody standing
 * outside a meeting room cares about extraction runs — they care who said it,
 * whether anyone checked, and whether it is safe to repeat. The ochre receipt
 * stops short on purpose: it is something a colleague said yesterday that
 * nobody has confirmed, and the card says so before you quote it.
 */

interface ReceiptRow {
  readonly detail: string;
  readonly label: string;
}

interface Receipt {
  readonly id: string;
  readonly kind: "checked" | "unchecked";
  readonly quote: string;
  readonly rows: readonly ReceiptRow[];
  readonly verdict: string;
}

const RECEIPTS: readonly Receipt[] = [
  {
    id: "6a70f2",
    kind: "checked",
    quote:
      "„Die überarbeitete Fassung brauchen sie bis Ende August, sonst rutscht das Ganze ins nächste Quartal.“",
    rows: [
      { detail: "Their procurement lead, in writing", label: "Who said it" },
      { detail: "A forwarded mail thread, 1 July", label: "Where from" },
      { detail: "Eric, the same morning", label: "Who checked it" },
      { detail: "Nothing since has contradicted it", label: "Still good?" },
    ],
    verdict: "Safe to say out loud.",
  },
  {
    id: "8c14b9",
    kind: "checked",
    quote:
      "„…und bitte nichts vor zehn, die Anna macht ihre Entscheidungen am liebsten morgens, aber nicht früh.“",
    rows: [
      { detail: "Anna, on the call — Eric was there", label: "Who said it" },
      {
        detail: "Eric's memo on the drive back, 13 March",
        label: "Where from",
      },
      {
        detail: "Eric, next morning. He fixed the wording first.",
        label: "Who checked it",
      },
      { detail: "Held up for five months", label: "Still good?" },
    ],
    verdict: "Safe to say out loud.",
  },
  {
    id: "4d09e1",
    kind: "unchecked",
    quote:
      "„…klang so, als würde das Budget ins erste Quartal rutschen — muss ich aber noch bestätigen lassen.“",
    rows: [
      { detail: "Marie, reporting what she picked up", label: "Who said it" },
      { detail: "Her memo yesterday, 17:22", label: "Where from" },
      {
        detail: "Nobody yet — it is in today's queue",
        label: "Who checked it",
      },
      { detail: "It disagrees with the July mail", label: "Careful" },
    ],
    verdict: "Worth knowing. Don't quote it to them yet.",
  },
];

const findReceipt = (id: string) =>
  RECEIPTS.find((receipt) => receipt.id === id) ?? RECEIPTS[0];

const ReceiptChip = ({
  onSelect,
  receipt,
  selected,
}: {
  onSelect: (id: string) => void;
  receipt: Receipt;
  selected: boolean;
}) => {
  const select = useCallback(
    () => onSelect(receipt.id),
    [onSelect, receipt.id]
  );
  const checked = receipt.kind === "checked";

  return (
    <button
      aria-expanded={selected}
      className={cn(
        // JSX drops the newline between the preceding word and this tag, so
        // the chip carries its own leading space — and none on the right, so
        // the full stop after a receipt sits where a full stop belongs.
        "ml-1 inline-flex translate-y-[-0.06em] items-center gap-1.5 rounded-[3px] px-1.5 py-0.5 align-baseline font-medium font-mono text-[0.6875rem] leading-none transition-colors",
        "focus-visible:outline-2 focus-visible:outline-mn-ink focus-visible:outline-offset-2",
        checked
          ? "bg-mn-stamp-tint text-mn-stamp hover:bg-mn-stamp hover:text-mn-paper"
          : "bg-mn-ochre-tint text-mn-ochre hover:bg-mn-ochre hover:text-mn-paper",
        selected &&
          (checked ? "bg-mn-stamp text-mn-paper" : "bg-mn-ochre text-mn-paper")
      )}
      onClick={select}
      type="button"
    >
      <span
        aria-hidden="true"
        className={cn(
          "size-1.5 rounded-[1px]",
          checked ? "bg-current" : "border border-current"
        )}
      />
      {receipt.id}
      <span className="sr-only">
        {checked
          ? " — checked by someone, open the receipt"
          : " — nobody has checked this, open the receipt"}
      </span>
    </button>
  );
};

export function Trace() {
  const [selectedId, setSelectedId] = useState("8c14b9");
  const reduceMotion = useReducedMotion();
  const receipt = findReceipt(selectedId);
  const checked = receipt.kind === "checked";

  return (
    <figure className="overflow-hidden rounded-lg border border-mn-rule bg-mn-raised shadow-[0_1px_0_var(--color-mn-rule),0_18px_50px_-32px_rgb(20_22_26/0.45)]">
      <figcaption className="flex items-center justify-between border-mn-rule border-b px-5 py-3 font-medium font-mono text-[0.625rem] text-mn-graphite uppercase tracking-[0.18em]">
        <span>09:58</span>
        <span>Two minutes before the call</span>
      </figcaption>

      <div className="px-5 pt-5 pb-4">
        <p className="font-bold font-cabinet text-[1.375rem] text-mn-ink leading-[1.2] tracking-[-0.02em]">
          What do I need to know before I talk to Nordwind?
        </p>
        <p className="mt-4 text-[0.9375rem] text-mn-ink-soft leading-[1.75]">
          They need the revised quote by the end of August, or it slips a
          quarter
          <ReceiptChip
            onSelect={setSelectedId}
            receipt={RECEIPTS[0]}
            selected={selectedId === "6a70f2"}
          />
          . Anna Bergmann signs it off, and she only decides things late morning
          <ReceiptChip
            onSelect={setSelectedId}
            receipt={RECEIPTS[1]}
            selected={selectedId === "8c14b9"}
          />
          . One thing to be careful with: Marie heard yesterday that the budget
          may move to Q1
          <ReceiptChip
            onSelect={setSelectedId}
            receipt={RECEIPTS[2]}
            selected={selectedId === "4d09e1"}
          />
          {" — nobody has checked that yet."}
        </p>
      </div>

      <div className="border-mn-rule border-t bg-mn-paper/70 px-5 py-4">
        <p className="font-medium font-mono text-[0.625rem] text-mn-graphite uppercase tracking-[0.18em]">
          Receipt {receipt.id}
        </p>

        <AnimatePresence initial={false} mode="wait">
          <motion.div
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            initial={{ opacity: reduceMotion ? 1 : 0 }}
            key={receipt.id}
            transition={{ duration: reduceMotion ? 0 : 0.18 }}
          >
            <ol className="mt-3.5 space-y-0">
              {receipt.rows.map((row, index) => (
                <li className="relative flex gap-3 pb-3.5 pl-4" key={row.label}>
                  <span
                    aria-hidden="true"
                    className={cn(
                      "absolute top-[0.3rem] left-0 size-1.5 rounded-full",
                      checked ? "bg-mn-stamp" : "bg-mn-ochre"
                    )}
                  />
                  {index < receipt.rows.length - 1 ? (
                    <span
                      aria-hidden="true"
                      className="absolute top-[0.7rem] bottom-0 left-[0.1875rem] w-px bg-mn-rule"
                    />
                  ) : null}
                  <span className="w-[6.75rem] shrink-0 font-medium font-mono text-[0.6875rem] text-mn-graphite uppercase leading-[1.5] tracking-[0.05em]">
                    {row.label}
                  </span>
                  <span className="text-[0.8125rem] text-mn-ink-soft leading-[1.5]">
                    {row.detail}
                  </span>
                </li>
              ))}
            </ol>

            <blockquote
              className={cn(
                "border-l-2 py-1 pl-3.5 text-[0.875rem] text-mn-ink leading-[1.6]",
                checked ? "border-mn-stamp" : "border-mn-ochre"
              )}
              lang="de"
            >
              {receipt.quote}
            </blockquote>

            <p
              className={cn(
                "mt-3.5 font-medium font-mono text-[0.6875rem] leading-[1.5]",
                checked ? "text-mn-stamp" : "text-mn-ochre"
              )}
            >
              {receipt.verdict}
            </p>
          </motion.div>
        </AnimatePresence>
      </div>
    </figure>
  );
}

