"use client";

import { cn } from "@repo/design-system/lib/utils";
import {
  BrainIcon,
  ClipboardCheckIcon,
  type LucideIcon,
  MicIcon,
  UsersIcon,
} from "lucide-react";
import { type ReactNode, useCallback, useState } from "react";

type MemoryTab = "capture" | "people" | "review";
type View = MemoryTab | "ask";

interface BrainWorkspaceProperties {
  readonly ask: ReactNode;
  readonly capture: ReactNode;
  readonly openReviewCount: number;
  readonly people: ReactNode;
  readonly review: ReactNode;
}

const MEMORY_TABS: { icon: LucideIcon; key: MemoryTab; label: string }[] = [
  { icon: MicIcon, key: "capture", label: "Capture" },
  { icon: ClipboardCheckIcon, key: "review", label: "Review" },
  { icon: UsersIcon, key: "people", label: "People" },
];

const SegmentButton = ({
  active,
  count,
  icon: Icon,
  label,
  onSelect,
  value,
}: {
  active: boolean;
  count?: number;
  icon: LucideIcon;
  label: string;
  onSelect: (view: View) => void;
  value: View;
}) => {
  const select = useCallback(() => onSelect(value), [onSelect, value]);

  return (
    <button
      aria-pressed={active}
      className={cn(
        "inline-flex h-full flex-1 items-center justify-center gap-1.5 whitespace-nowrap rounded-md border border-transparent px-2 py-1 font-medium text-sm transition-[color,box-shadow] focus-visible:outline-1 focus-visible:outline-ring focus-visible:ring-[3px] focus-visible:ring-ring/50",
        active
          ? "bg-background text-foreground shadow-sm dark:border-input dark:bg-input/30"
          : "text-muted-foreground hover:text-foreground"
      )}
      onClick={select}
      type="button"
    >
      <Icon className="size-4 shrink-0" />
      {label}
      {count !== undefined && count > 0 ? (
        <span className="inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 font-medium text-[10px] text-primary-foreground tabular-nums">
          {count}
        </span>
      ) : null}
    </button>
  );
};

/**
 * The whole brain on one screen: the conversation as the main pane, and a
 * memory rail beside it for what goes in (Capture), what awaits judgment
 * (Review) and who the brain knows (People). On small screens the rail and the
 * conversation share the viewport, toggled by the strip on top; the chat stays
 * mounted throughout so the conversation survives tab hopping.
 */
export const BrainWorkspace = ({
  ask,
  capture,
  openReviewCount,
  people,
  review,
}: BrainWorkspaceProperties) => {
  const [view, setView] = useState<View>("ask");
  // The rail is always visible on desktop, where "ask" isn't a tab — fall
  // back to whatever needs the user: the review queue when it has entries.
  const defaultMemory: MemoryTab = openReviewCount > 0 ? "review" : "capture";
  const memory: MemoryTab = view === "ask" ? defaultMemory : view;

  const panes: { key: MemoryTab; node: ReactNode }[] = [
    { key: "capture", node: capture },
    { key: "review", node: review },
    { key: "people", node: people },
  ];

  return (
    // Explicit viewport-derived height: every ancestor only has min-height,
    // so a flex chain cannot bound this pane — content height would
    // propagate up and move scrolling to the page, which disables the
    // conversation's stick-to-bottom. 4rem is the header; md+ adds the inset
    // shell's vertical margins (m-2 → 1rem).
    <div className="flex h-[calc(100svh-4rem)] flex-col gap-4 overflow-hidden p-4 pt-0 md:h-[calc(100svh-5rem)]">
      <div className="flex h-9 items-center rounded-lg bg-muted p-[3px] lg:hidden">
        <SegmentButton
          active={view === "ask"}
          icon={BrainIcon}
          label="Ask"
          onSelect={setView}
          value="ask"
        />
        {MEMORY_TABS.map((tab) => (
          <SegmentButton
            active={view === tab.key}
            count={tab.key === "review" ? openReviewCount : undefined}
            icon={tab.icon}
            key={tab.key}
            label={tab.label}
            onSelect={setView}
            value={tab.key}
          />
        ))}
      </div>
      <div className="flex min-h-0 flex-1 gap-6">
        <section
          className={cn(
            "min-h-0 min-w-0 flex-1 flex-col",
            view === "ask" ? "flex" : "hidden lg:flex"
          )}
        >
          {ask}
        </section>
        <aside
          className={cn(
            "min-h-0 w-full flex-col gap-4 lg:w-[380px] lg:shrink-0 lg:border-l lg:pl-6",
            view === "ask" ? "hidden lg:flex" : "flex"
          )}
        >
          <div className="hidden h-9 items-center rounded-lg bg-muted p-[3px] lg:flex">
            {MEMORY_TABS.map((tab) => (
              <SegmentButton
                active={memory === tab.key}
                count={tab.key === "review" ? openReviewCount : undefined}
                icon={tab.icon}
                key={tab.key}
                label={tab.label}
                onSelect={setView}
                value={tab.key}
              />
            ))}
          </div>
          <div className="min-h-0 flex-1 overflow-y-auto">
            {panes.map((pane) => (
              <div
                className={memory === pane.key ? "block" : "hidden"}
                key={pane.key}
              >
                {pane.node}
              </div>
            ))}
          </div>
        </aside>
      </div>
    </div>
  );
};

"use client";

import {
  InlineCitation,
  InlineCitationCard,
  InlineCitationCardBody,
} from "@repo/design-system/components/ai-elements/inline-citation";
import { Badge } from "@repo/design-system/components/ui/badge";
import { HoverCardTrigger } from "@repo/design-system/components/ui/hover-card";

// Every fact the agent has returned in this conversation, keyed by the id it
// must cite. Built from tool output rather than from the prose, so a claim can
// only cite something the knowledge base actually returned.
export interface CitedFact {
  category: string;
  confidence: number;
  id: string;
  text: string;
  validFrom: string | null;
}

// The category enum values are storage keys, not UI copy.
const CATEGORY_LABELS: Record<string, string> = {
  background: "Hintergrund",
  "decision-process": "Entscheidungsweg",
  logistics: "Logistik",
  objection: "Einwand",
  other: "Sonstiges",
  preference: "Präferenz",
  relationship: "Beziehung",
};

const categoryLabel = (category: string): string =>
  CATEGORY_LABELS[category] ?? category;

const germanDate = (iso: string | null) =>
  iso
    ? new Date(iso).toLocaleDateString("de-DE", { dateStyle: "medium" })
    : null;

// Streamdown's sanitizer rewrites `id` attributes to "user-content-…" as
// DOM-clobbering protection (the GitHub convention), so the attribute arrives
// prefixed even though the model emitted the bare fact id. Strip it before
// resolving against the retrieved facts.
const CLOBBER_PREFIX = /^user-content-/;

/**
 * Renders one `<fact id="…"/>` marker the model emitted inline.
 *
 * An id we never returned is shown as broken rather than dropped. A dropped
 * citation is indistinguishable from an uncited claim, which is precisely the
 * failure this whole mechanism exists to make visible.
 */
export const FactCitation = ({
  facts,
  id,
}: {
  facts: Map<string, CitedFact>;
  id?: string;
}) => {
  const factId = id?.replace(CLOBBER_PREFIX, "");
  const fact = factId ? facts.get(factId) : undefined;

  if (!fact) {
    // Same hover-card interaction as a resolved citation, so the broken
    // marker explains itself instead of relying on the native title tooltip.
    return (
      <InlineCitation>
        <InlineCitationCard>
          <HoverCardTrigger asChild>
            <button
              className="ml-0.5 cursor-help rounded bg-destructive/10 px-1 align-super font-medium text-destructive text-xs"
              type="button"
            >
              ?
            </button>
          </HoverCardTrigger>
          <InlineCitationCardBody className="w-80 overflow-hidden">
            <div className="px-4 py-3.5">
              <p className="font-medium text-destructive text-sm">
                Unbelegtes Zitat
              </p>
              <p className="mt-1 text-muted-foreground text-xs leading-relaxed">
                Die Wissensdatenbank hat den zitierten Fakt in dieser
                Unterhaltung nicht geliefert. Diese Aussage ist damit nicht
                belegt.
              </p>
            </div>
            {factId ? (
              <footer className="border-t bg-muted/30 px-4 py-2">
                <span className="font-mono text-[10px] text-muted-foreground">
                  Fakt {factId}
                </span>
              </footer>
            ) : null}
          </InlineCitationCardBody>
        </InlineCitationCard>
      </InlineCitation>
    );
  }

  const since = germanDate(fact.validFrom);
  const confidence = Math.round(fact.confidence * 100);

  return (
    <InlineCitation>
      <InlineCitationCard>
        <HoverCardTrigger asChild>
          <Badge
            asChild
            className="ml-1 cursor-help rounded-full"
            variant="secondary"
          >
            <button type="button">{categoryLabel(fact.category)}</button>
          </Badge>
        </HoverCardTrigger>
        <InlineCitationCardBody className="w-80 overflow-hidden">
          <blockquote className="px-4 py-3.5 text-sm leading-relaxed">
            <span aria-hidden className="text-muted-foreground">
              „
            </span>
            {fact.text}
            <span aria-hidden className="text-muted-foreground">
              “
            </span>
          </blockquote>
          <footer className="flex items-center justify-between gap-3 border-t bg-muted/30 px-4 py-2 text-muted-foreground text-xs">
            <span>{since ? `gültig seit ${since}` : " "}</span>
            <span className="tabular-nums">
              Konfidenz{" "}
              <span className="font-medium text-foreground">
                {confidence}&thinsp;%
              </span>
            </span>
          </footer>
        </InlineCitationCardBody>
      </InlineCitationCard>
    </InlineCitation>
  );
};

import { defineAgent } from "eve";

// The chat surface over the knowledge base. Retrieval is a tool rather than
// pre-stuffed context: the model decides what to look up, and the reader can
// see which facts an answer rests on.
//
// The model is routed through the Vercel AI Gateway, the same path the
// extraction worker uses. KNOWLEDGE_CHAT_MODEL overrides it per environment
// without a code change.
export default defineAgent({
  model: process.env.KNOWLEDGE_CHAT_MODEL ?? "deepseek/deepseek-v4-flash-0731",
});

import { authInstance } from "@repo/auth/instance";
import { localDev } from "eve/channels/auth";
import { eveChannel } from "eve/channels/eve";

// The agent's front door. eve rejects unauthenticated traffic by default; this
// replaces the scaffold's placeholder with the app's own better-auth session,
// so the browser's existing cookie is the credential and there is no second
// token to mint or keep in sync.
//
// The tenant is stamped from the verified session's active organization and
// from nowhere else. Tools re-read it off ctx.session.auth rather than taking
// it as an argument, so a model that invents a tenant id cannot reach another
// organization's facts.
const betterAuthSession = async (request: Request) => {
  const session = await authInstance.api.getSession({
    headers: request.headers,
  });
  const userId = session?.user.id;
  const tenantId = session?.session.activeOrganizationId;

  // Returning null skips to the next verifier rather than accepting: a signed-in
  // user with no active organization has no tenant, and guessing one would be
  // the whole ballgame.
  if (!(userId && tenantId)) {
    return null;
  }

  return {
    attributes: { tenantId },
    authenticator: "better-auth",
    principalId: userId,
    principalType: "user" as const,
  };
};

/**
 * Whether this process is a local development server, mirroring the rule
 * eve's own localDev() applies: `eve dev` (EVE_DEV=1) or `vercel dev`
 * (VERCEL=1 with VERCEL_ENV=development). eve 0.30.0 rebased localDev() onto
 * this deployment property and removed the isLoopbackRequest() helper this
 * file used to gate on, because a request's Host header is attacker-supplied
 * and could hand out local-dev access on a self-hosted server.
 *
 * Duplicated rather than imported: eve keeps its equivalent internal.
 */
const isLocalDevelopmentServer = () =>
  (Boolean(process.env.VERCEL) && process.env.VERCEL_ENV === "development") ||
  process.env.EVE_DEV === "1";

/**
 * Stamps a tenant onto eval sessions. `eve eval` drives the agent over HTTP
 * with no better-auth cookie, so the auth walk falls through to localDev(),
 * whose attributes are empty — and search-knowledge then throws because it
 * reads tenantId off the verified session and from nowhere else.
 *
 * This grants no access that is not already granted: `eve eval` starts its own
 * development server, so EVE_DEV=1 and localDev() already admits every request
 * to it unauthenticated. This only adds an attribute to a principal that
 * already gets in, and it gates on the identical condition, so it can never
 * accept a request localDev() would have refused. EVAL_TENANT_ID is also unset
 * in production, so it returns null before the deployment check matters.
 *
 * Exported for test. Deliberately NOT a fallback default inside the tool —
 * guessing a tenant is the whole ballgame.
 */
export const evalTenant = (_request: Request) => {
  const tenantId = process.env.EVAL_TENANT_ID;
  if (!(tenantId && isLocalDevelopmentServer())) {
    return null;
  }
  return {
    attributes: { tenantId },
    authenticator: "eval",
    principalId: "eval",
    principalType: "user" as const,
  };
};

// Exported (not just inlined below) so a test can pin the order: evalTenant
// must run before localDev(), or an eval request never reaches it — localDev()
// accepts every request to a local development server, which is exactly where
// evals run, so if it came first it would win every time and evalTenant would
// become dead code with every test still green (this is what F1's fix actually
// depends on).
export const channelAuth = [betterAuthSession, evalTenant, localDev()];

// NOTE: route auth authenticates the caller, it does not prove that this caller
// owns the session id in the URL. eve treats a session id as a bearer
// capability, so before this is exposed beyond internal users we need to
// persist session → tenant ownership and check it on resume and on stream.
export default eveChannel({
  auth: channelAuth,
});

