import {
  createVoyageRerank,
  type Fact,
  factCategoryValues,
  retrieveFacts,
} from "@repo/knowledge";
import { getKnowledgeDb } from "@repo/knowledge/client";
import { defineTool } from "eve/tools";
import { z } from "zod";

// Built once, not per call, and only when a key is configured — without one
// the read path still works, it just returns fusion order instead of
// cross-encoder order.
let rerank: ReturnType<typeof createVoyageRerank<Fact>> | null | undefined;
const getRerank = () => {
  if (rerank === undefined) {
    rerank = process.env.VOYAGE_API_KEY ? createVoyageRerank<Fact>() : null;
  }
  return rerank ?? undefined;
};

export default defineTool({
  description:
    "Search the company knowledge base for confirmed facts about people, organizations and engagements. Call this before answering any question about who someone is, what a client wants, or what was decided — you have no knowledge of this company otherwise. Returns each fact with the id you must cite it by.",
  async execute(input, ctx) {
    // The tenant comes from the verified session, never from the model. A
    // tenantId in the tool input would be attacker-reachable through prompt
    // injection in any ingested email.
    const tenantId = ctx.session.auth.current?.attributes?.tenantId;
    if (typeof tenantId !== "string" || tenantId.length === 0) {
      throw new Error(
        "No active organization on this session; cannot search the knowledge base."
      );
    }

    const results = await retrieveFacts(getKnowledgeDb(), {
      category: input.category,
      query: input.query,
      rerank: getRerank(),
      tenantId,
    });

    return {
      // Shaped for citation: the id is the thing the model has to reproduce
      // exactly, so it leads. Dates and ObjectIds are stringified because tool
      // output crosses a durable JSON boundary.
      facts: results.map(({ fact, relevanceScore }) => ({
        category: fact.category,
        confidence: fact.confidence,
        id: fact._id.toHexString(),
        relevanceScore,
        text: fact.text,
        validFrom: fact.validFrom?.toISOString() ?? null,
      })),
      searched: input.query,
    };
  },
  inputSchema: z.object({
    category: z
      .enum(factCategoryValues)
      .optional()
      .describe(
        "Narrow to one kind of fact. Omit unless the question is clearly about only one — narrowing costs recall."
      ),
    query: z
      .string()
      .min(1)
      .describe(
        "What to look for, in the language the facts are likely written in. A name, a topic, or a short phrase works better than a full sentence."
      ),
  }),
});

"use client";

import {
  InlineCitation,
  InlineCitationCard,
  InlineCitationCardBody,
} from "@repo/design-system/components/ai-elements/inline-citation";
import { Badge } from "@repo/design-system/components/ui/badge";
import { HoverCardTrigger } from "@repo/design-system/components/ui/hover-card";

// Every raw source the agent has returned in this conversation, keyed by the
// id it must cite. Built from tool output rather than from the prose — same
// contract as CitedFact, for the unverified tier.
export interface CitedSource {
  capturedAt: string | null;
  capturedBy: string;
  excerpt: string;
  id: string;
  occurredAt: string | null;
  reviewed: boolean;
  subject: string | null;
  type: string;
}

const TYPE_LABELS: Record<string, string> = {
  email: "E-Mail",
  manual: "Notiz",
  voice: "Sprachmemo",
};

const typeLabel = (type: string): string => TYPE_LABELS[type] ?? type;

const germanDate = (iso: string | null) =>
  iso
    ? new Date(iso).toLocaleDateString("de-DE", { dateStyle: "medium" })
    : null;

// Streamdown's sanitizer rewrites `id` attributes to "user-content-…" as
// DOM-clobbering protection — same handling as FactCitation.
const CLOBBER_PREFIX = /^user-content-/;

// The hovercard quotes at most this much; the excerpt itself is already a
// database-side truncation of the full content.
const PREVIEW_LENGTH = 280;

/**
 * Renders one `<source id="…"/>` marker the model emitted inline. Visually
 * distinct from a fact citation: an outline badge with the capture channel,
 * and an explicit "ungeprüft" flag while no reviewer has confirmed the
 * source's proposal — the reader must be able to tell the two tiers apart at
 * a glance.
 */
export const SourceCitation = ({
  id,
  sources,
}: {
  id?: string;
  sources: Map<string, CitedSource>;
}) => {
  const sourceId = id?.replace(CLOBBER_PREFIX, "");
  const source = sourceId ? sources.get(sourceId) : undefined;

  if (!source) {
    return (
      <InlineCitation>
        <InlineCitationCard>
          <HoverCardTrigger asChild>
            <button
              className="ml-0.5 cursor-help rounded bg-destructive/10 px-1 align-super font-medium text-destructive text-xs"
              type="button"
            >
              ?
            </button>
          </HoverCardTrigger>
          <InlineCitationCardBody className="w-80 overflow-hidden">
            <div className="px-4 py-3.5">
              <p className="font-medium text-destructive text-sm">
                Unbelegtes Zitat
              </p>
              <p className="mt-1 text-muted-foreground text-xs leading-relaxed">
                Die Suche hat die zitierte Quelle in dieser Unterhaltung nicht
                geliefert. Diese Aussage ist damit nicht belegt.
              </p>
            </div>
            {sourceId ? (
              <footer className="border-t bg-muted/30 px-4 py-2">
                <span className="font-mono text-[10px] text-muted-foreground">
                  Quelle {sourceId}
                </span>
              </footer>
            ) : null}
          </InlineCitationCardBody>
        </InlineCitationCard>
      </InlineCitation>
    );
  }

  const captured = germanDate(source.capturedAt);
  const preview =
    source.excerpt.length > PREVIEW_LENGTH
      ? `${source.excerpt.slice(0, PREVIEW_LENGTH)}…`
      : source.excerpt;

  return (
    <InlineCitation>
      <InlineCitationCard>
        <HoverCardTrigger asChild>
          <Badge
            asChild
            className="ml-1 cursor-help rounded-full"
            variant="outline"
          >
            <button type="button">
              {typeLabel(source.type)}
              {source.reviewed ? "" : " · ungeprüft"}
            </button>
          </Badge>
        </HoverCardTrigger>
        <InlineCitationCardBody className="w-80 overflow-hidden">
          <div className="px-4 py-3.5">
            {source.subject ? (
              <p className="mb-1 font-medium text-sm">{source.subject}</p>
            ) : null}
            <blockquote className="text-sm leading-relaxed">
              <span aria-hidden className="text-muted-foreground">
                „
              </span>
              {preview}
              <span aria-hidden className="text-muted-foreground">
                “
              </span>
            </blockquote>
            {source.reviewed ? null : (
              <p className="mt-2 text-muted-foreground text-xs leading-relaxed">
                Rohmaterial — noch von niemandem geprüft.
              </p>
            )}
          </div>
          <footer className="flex items-center justify-between gap-3 border-t bg-muted/30 px-4 py-2 text-muted-foreground text-xs">
            <span className="truncate">{source.capturedBy}</span>
            <span>{captured ? `erfasst ${captured}` : " "}</span>
          </footer>
        </InlineCitationCardBody>
      </InlineCitationCard>
    </InlineCitation>
  );
};

import { z } from "zod";
import { baseDocFields, zodObjectId } from "./shared";

export const factCategoryValues = [
  "preference",
  "objection",
  "decision-process",
  "relationship",
  "logistics",
  "background",
  "other",
] as const;
export type FactCategory = (typeof factCategoryValues)[number];

export const factAnchorsSchema = z
  .object({
    engagementId: zodObjectId.optional(),
    organizationId: zodObjectId.optional(),
    personId: zodObjectId.optional(),
  })
  .refine(
    (anchors) =>
      Boolean(
        anchors.organizationId || anchors.personId || anchors.engagementId
      ),
    { message: "A fact must be anchored to at least one entity" }
  );
export type FactAnchors = z.infer<typeof factAnchorsSchema>;

// The lifecycle convention in queryable form: a fact is currently valid iff
// both fields are absent, and { field: null } matches null-or-missing. Share
// this everywhere (search, dossier reads, ask tools) instead of re-typing it.
export const currentlyValidFilter = {
  supersededBy: null,
  validUntil: null,
} as const;

export const factSchema = z
  .object({
    ...baseDocFields,
    anchors: factAnchorsSchema,
    category: z.enum(factCategoryValues),
    confidence: z.number().min(0).max(1),
    confirmedBy: z.string().min(1),
    // Provenance for consolidated facts: the facts this one was merged from.
    derivedFrom: z.array(zodObjectId).min(1).optional(),
    // Stubbed for later semantic search (EU embedding provider).
    embedding: z.array(z.number()).optional(),
    sourceId: zodObjectId.optional(),
    // System time end, written alongside supersededBy: when we stopped
    // believing this fact. validUntil says when it stopped being *true* —
    // the two differ whenever we learn about a change after it happened.
    supersededAt: z.date().nullish(),
    // Lifecycle fields are nullish, not just optional: the convention treats
    // null and missing alike, so the stored form the filter tolerates (and
    // the driver's Filter type derives from) must admit null too.
    supersededBy: zodObjectId.nullish(),
    text: z.string().min(1),
    // Event time start: when the fact became true in the world, as distinct
    // from createdAt (when we recorded it). An ingestion fact inherits it
    // from its source's occurredAt; a merge inherits its earliest parent's.
    validFrom: z.date().optional(),
    // Lifecycle (dream cycle): a fact is currently valid iff BOTH are absent.
    validUntil: z.date().nullish(),
  })
  .refine((fact) => Boolean(fact.sourceId || fact.derivedFrom?.length), {
    message:
      "A fact needs provenance: a sourceId (ingestion) or derivedFrom (consolidation)",
  });
export type Fact = z.infer<typeof factSchema>;

