import type { Db, ObjectId } from "mongodb";
import { z } from "zod";
import { getCollections } from "./collections";
import { deterministicId } from "./idempotency";
import {
  currentlyValidFilter,
  type Fact,
  factCategoryValues,
} from "./schemas/facts";
import { baseDocFields, zodObjectId } from "./schemas/shared";

// The always-loadable tier: a budgeted per-anchor summary materialized from
// currently valid facts, cheap enough to inject into any agent context or
// UI header, while the full fact set stays behind search. Deterministic
// composition — no LLM call — so a refresh is safe to run on every change.

export const dossierAnchorKinds = [
  "engagement",
  "organization",
  "person",
] as const;

export const dossierSchema = z.object({
  ...baseDocFields,
  anchor: z.object({
    id: zodObjectId,
    kind: z.enum(dossierAnchorKinds),
  }),
  content: z.string(),
  factCount: z.number().int().min(0),
});
export type Dossier = z.infer<typeof dossierSchema>;

export interface DossierAnchor {
  id: ObjectId;
  kind: (typeof dossierAnchorKinds)[number];
}

const DEFAULT_BUDGET_TOKENS = 600;
/** chars-per-token heuristic; content is prose, so 4 is conservative. */
const CHARS_PER_TOKEN = 4;

export const composeDossier = (
  anchorName: string,
  facts: Fact[],
  { budgetTokens = DEFAULT_BUDGET_TOKENS }: { budgetTokens?: number } = {}
): string => {
  const budgetChars = budgetTokens * CHARS_PER_TOKEN;
  const header = `# ${anchorName}\n`;

  // Newest first: when the budget runs out, it is the oldest facts that drop.
  const byRecency = [...facts].sort(
    (a, b) => b.updatedAt.getTime() - a.updatedAt.getTime()
  );

  let used = header.length;
  const kept: Fact[] = [];
  for (const fact of byRecency) {
    const line = `- ${fact.text}\n`;
    if (used + line.length > budgetChars) {
      break;
    }
    used += line.length;
    kept.push(fact);
  }

  const sections: string[] = [header];
  for (const category of factCategoryValues) {
    const inCategory = kept.filter((fact) => fact.category === category);
    if (inCategory.length === 0) {
      continue;
    }
    sections.push(
      `\n## ${category}\n${inCategory.map((fact) => `- ${fact.text}`).join("\n")}\n`
    );
  }
  const dropped = facts.length - kept.length;
  if (dropped > 0) {
    sections.push(`\n(+${dropped} older facts beyond the budget)\n`);
  }
  return sections.join("");
};

const anchorFilter = (anchor: DossierAnchor) => {
  switch (anchor.kind) {
    case "engagement":
      return { "anchors.engagementId": anchor.id };
    case "organization":
      return { "anchors.organizationId": anchor.id };
    default:
      return { "anchors.personId": anchor.id };
  }
};

const resolveAnchorName = async (
  db: Db,
  tenantId: string,
  anchor: DossierAnchor
): Promise<string> => {
  const { engagements, organizations, people } = getCollections(db);
  if (anchor.kind === "organization") {
    const doc = await organizations.findOne({ _id: anchor.id, tenantId });
    return doc?.name ?? "unknown";
  }
  if (anchor.kind === "person") {
    const doc = await people.findOne({ _id: anchor.id, tenantId });
    return doc?.name ?? "unknown";
  }
  const doc = await engagements.findOne({ _id: anchor.id, tenantId });
  return doc?.title ?? "unknown";
};

export const refreshDossier = async (
  db: Db,
  tenantId: string,
  anchor: DossierAnchor,
  options: { budgetTokens?: number } = {}
): Promise<Dossier | null> => {
  const { dossiers, facts } = getCollections(db);

  const validFacts = await facts
    .find({ tenantId, ...anchorFilter(anchor), ...currentlyValidFilter })
    .sort({ updatedAt: -1 })
    .toArray();

  if (validFacts.length === 0) {
    await dossiers.deleteMany({
      "anchor.id": anchor.id,
      "anchor.kind": anchor.kind,
      tenantId,
    });
    return null;
  }

  const name = await resolveAnchorName(db, tenantId, anchor);
  const writtenAt = new Date();
  const doc: Dossier = {
    _id: deterministicId(
      `${tenantId}:dossier:${anchor.kind}:${anchor.id.toHexString()}`
    ),
    anchor,
    content: composeDossier(name, validFacts, options),
    createdAt: writtenAt,
    factCount: validFacts.length,
    tenantId,
    updatedAt: writtenAt,
  };
  await dossiers.updateOne(
    { _id: doc._id, tenantId },
    {
      $set: {
        anchor: doc.anchor,
        content: doc.content,
        factCount: doc.factCount,
        updatedAt: writtenAt,
      },
      $setOnInsert: { createdAt: writtenAt, tenantId },
    },
    { upsert: true }
  );
  return doc;
};

import { retrieveSources } from "@repo/knowledge";
import { getKnowledgeDb } from "@repo/knowledge/client";
import { defineTool } from "eve/tools";
import { z } from "zod";

// The unverified tier of the ask surface: raw captured material is
// searchable the moment it lands, hours to days before a reviewer distills
// any of it into confirmed facts. The tool exists so "what did we ingest
// this morning?" has an answer before the review queue has been worked.

export default defineTool({
  description:
    "Search the raw captured sources — voice-memo transcripts, forwarded emails, pasted notes — including material no reviewer has confirmed yet. Use this when search-knowledge returns nothing or too little, or when the question concerns something captured very recently. Everything returned is UNVERIFIED raw material: attribute it to its source when you use it, never present it as established fact.",
  async execute(input, ctx) {
    // The tenant comes from the verified session, never from the model. A
    // tenantId in the tool input would be attacker-reachable through prompt
    // injection in any ingested email.
    const tenantId = ctx.session.auth.current?.attributes?.tenantId;
    if (typeof tenantId !== "string" || tenantId.length === 0) {
      throw new Error(
        "No active organization on this session; cannot search sources."
      );
    }

    const hits = await retrieveSources(getKnowledgeDb(), {
      query: input.query,
      tenantId,
      ...(input.type ? { type: input.type } : {}),
    });

    return {
      searched: input.query,
      // Shaped for citation, like search-knowledge: the id leads. Dates and
      // ObjectIds are stringified because tool output crosses a durable JSON
      // boundary.
      sources: hits.map((hit) => ({
        capturedAt: hit.createdAt?.toISOString() ?? null,
        capturedBy: hit.capturedBy,
        excerpt: hit.excerpt,
        id: hit._id.toHexString(),
        occurredAt: hit.occurredAt?.toISOString() ?? null,
        // "reviewed" means a human worked this source's proposal — anything
        // else is still waiting on review.
        reviewed: hit.status === "reviewed",
        subject: hit.email?.subject ?? null,
        type: hit.type,
      })),
    };
  },
  inputSchema: z.object({
    query: z
      .string()
      .min(1)
      .describe(
        "What to look for, in the language the source is likely written in. A name, a topic, or a short phrase works better than a full sentence."
      ),
    type: z
      .enum(["voice", "email", "manual"])
      .optional()
      .describe(
        "Narrow to one capture channel. Omit unless the question names one — narrowing costs recall."
      ),
  }),
});

