1	import type { Db, Document, ObjectId } from "mongodb";
2	import { getCollections } from "./collections";
3	import type { GatewayUsage, UsageContext } from "./gateway";
4	import type { Fact } from "./schemas/facts";
5	import { currentlyValidFilter, type FactCategory } from "./schemas/facts";
6	import type { Source } from "./schemas/sources";
7	import {
8	  buildSourcesSearchPipeline,
9	  FACTS_SEARCH_INDEX_NAME,
10	  type SourcesSearchOptions,
11	} from "./search";
12	
13	// The read path. Facts are written by extraction, consolidation, contradiction
14	// and review; until now nothing read them back.
15	//
16	// Retrieval is hybrid because German makes it necessary: compound nouns,
17	// internal jargon and product identifiers are exactly what dense embeddings
18	// lose, and on German legal retrieval BM25 beats every dense model outright.
19	// A lexical arm and a semantic arm are fused with reciprocal rank fusion, then
20	// a cross-encoder reranks the survivors.
21	
22	export const FACTS_VECTOR_INDEX_NAME = "facts_vector";
23	
24	/**
25	 * Automated Embedding: Atlas generates the vectors for `text` at index time
26	 * and for the query at search time, so no embedding column is stored on the
27	 * document and no embedding call happens in this process.
28	 *
29	 * `numDimensions` and `model` are immutable once the index exists — changing
30	 * either means rebuilding it. 2048 is voyage-4-large's native width and sits
31	 * above the 1024 floor Atlas recommends for quantized workloads.
32	 */
33	export const factsVectorIndexDefinition = {
34	  fields: [
35	    {
36	      modality: "text",
37	      model: "voyage-4-large",
38	      numDimensions: 2048,
39	      path: "text",
40	      quantization: "scalar",
41	      type: "autoEmbed",
42	    },
43	    // Pre-filters, not post-filters: $vectorSearch returns k nearest
44	    // neighbours and *then* the pipeline continues, so filtering afterwards
45	    // would let another tenant's documents consume this tenant's k.
46	    { path: "tenantId", type: "filter" },
47	    { path: "category", type: "filter" },
48	  ],
49	} as const;
50	
51	/**
52	 * Lexical is weighted at least as heavily as semantic on purpose. German
53	 * compound nouns, ticket ids and product names are where dense retrieval is
54	 * weakest and where the lucene.german analyzer earns its keep.
55	 */
56	export const rankFusionWeights = { lexical: 0.5, semantic: 0.5 } as const;
57	
58	/** Each arm over-fetches relative to the final cut; fusion can only rank
59	 * what the arms surfaced, and the reranker wants headroom too. */
60	const CANDIDATE_MULTIPLIER = 5;
61	const NUM_CANDIDATES_MULTIPLIER = 20;
62	const DEFAULT_LIMIT = 20;
63	
64	export interface HybridFactsSearchOptions {
65	  category?: FactCategory;
66	  includeSuperseded?: boolean;
67	  limit?: number;
68	  query: string;
69	  tenantId: string;
70	}
71	
72	export const buildHybridFactsPipeline = ({
73	  category,
74	  includeSuperseded = false,
75	  limit = DEFAULT_LIMIT,
76	  query,
77	  tenantId,
78	}: HybridFactsSearchOptions): Document[] => {
79	  const perArm = limit * CANDIDATE_MULTIPLIER;
80	  const lifecycle: Document[] = includeSuperseded
81	    ? []
82	    : [{ $match: { ...currentlyValidFilter } }];
83	
84	  const lexicalFilter: Document[] = [
85	    { equals: { path: "tenantId", value: tenantId } },
86	  ];
87	  if (category) {
88	    lexicalFilter.push({ equals: { path: "category", value: category } });
89	  }
90	
91	  const vectorFilter: Document = { tenantId };
92	  if (category) {
93	    vectorFilter.category = category;
94	  }
95	
96	  return [
97	    {
98	      $rankFusion: {
99	        combination: { weights: { ...rankFusionWeights } },
100	        input: {
101	          pipelines: {
102	            lexical: [
103	              {
104	                $search: {
105	                  compound: {
106	                    filter: lexicalFilter,
107	                    must: [
108	                      {
109	                        text: {
110	                          fuzzy: { maxEdits: 1 },
111	                          // Both analyzer paths: the German multi for
112	                          // compound stemming and umlaut folding, the
113	                          // default for code-switched English.
114	                          path: ["text", { multi: "german", value: "text" }],
115	                          query,
116	                        },
117	                      },
118	                    ],
119	                  },
120	                  index: FACTS_SEARCH_INDEX_NAME,
121	                },
122	              },
123	              ...lifecycle,
124	              { $limit: perArm },
125	            ],
126	            semantic: [
127	              {
128	                $vectorSearch: {
129	                  filter: vectorFilter,
130	                  index: FACTS_VECTOR_INDEX_NAME,
131	                  limit: perArm,
132	                  numCandidates: limit * NUM_CANDIDATES_MULTIPLIER,
133	                  path: "text",
134	                  // Automated Embedding takes the query as text and embeds
135	                  // it server-side with the index's model.
136	                  query: { text: query },
137	                },
138	              },
139	              ...lifecycle,
140	            ],
141	          },
142	        },
143	        scoreDetails: true,
144	      },
145	    },
146	    { $limit: limit },
147	  ];
148	};
149	
150	export interface RetrievedFact {
151	  fact: Fact;
152	  /** Present only when a reranker ran. */
153	  relevanceScore?: number;
154	}
155	
156	export interface RetrieveFactsOptions extends HybridFactsSearchOptions {
157	  /**
158	   * Optional cross-encoder pass over the fused candidates. Omitted, results
159	   * come back in fusion order — useful for a cheap path, and the only option
160	   * until a rerank key is configured.
161	   */
162	  rerank?: (
163	    query: string,
164	    documents: Fact[]
165	  ) => Promise<RerankedDocument<Fact>[]>;
166	}
167	
168	/**
169	 * The callable read path: fuse the two arms in the database, then optionally
170	 * rerank. Needs Atlas — `$search` and `$vectorSearch` run on mongot, which a
171	 * plain mongod does not have, so this composition is verified against a live
172	 * cluster rather than in the local test suite.
173	 */
174	export const retrieveFacts = async (
175	  db: Db,
176	  { rerank, ...search }: RetrieveFactsOptions
177	): Promise<RetrievedFact[]> => {
178	  const { facts } = getCollections(db);
179	  const fused = await facts
180	    .aggregate<Fact>(buildHybridFactsPipeline(search))
181	    .toArray();
182	
183	  if (!rerank || fused.length === 0) {
184	    return fused.map((fact) => ({ fact }));
185	  }
186	  try {
187	    const ranked = await rerank(search.query, fused);
188	    return ranked.map(({ document, relevanceScore }) => ({
189	      fact: document,
190	      relevanceScore,
191	    }));
192	  } catch (error) {
193	    // A broken reranker (revoked key, endpoint down) must not blank out the
194	    // read path — fusion order is the documented result whenever no reranker
195	    // is configured, so it is also the fallback when one fails. The warning
196	    // keeps the misconfiguration discoverable.
197	    console.warn(
198	      `retrieveFacts: rerank failed, returning fusion order: ${
199	        error instanceof Error ? error.message : String(error)
200	      }`
201	    );
202	    return fused.map((fact) => ({ fact }));
203	  }
204	};
205	
206	/** What buildSourcesSearchPipeline's $project leaves of a matching source. */
207	export interface SourceSearchHit {
208	  _id: ObjectId;
209	  capturedBy: string;
210	  createdAt?: Date;
211	  email?: { subject: string };
212	  /** The first SOURCE_EXCERPT_LENGTH characters of the raw content. */
213	  excerpt: string;
214	  occurredAt?: Date;
215	  status: Source["status"];
216	  tenantId: string;
217	  type: Source["type"];
218	}
219	
220	/**
221	 * The unverified tier of the read path: raw captured material, searchable the
222	 * moment it lands rather than after extraction and review. Lexical only — no
223	 * fact has been distilled yet, so there is nothing sensible to embed — and
224	 * like retrieveFacts it needs mongot, so it is verified against a live
225	 * cluster rather than in the local test suite.
226	 */
227	export const retrieveSources = async (
228	  db: Db,
229	  options: SourcesSearchOptions
230	): Promise<SourceSearchHit[]> => {
231	  const { sources } = getCollections(db);
232	  return await sources
233	    .aggregate<SourceSearchHit>(buildSourcesSearchPipeline(options))
234	    .toArray();
235	};
236	
237	export interface RerankableDocument {
238	  text: string;
239	}
240	
241	export interface RerankedDocument<T extends RerankableDocument> {
242	  document: T;
243	  relevanceScore: number;
244	}
245	
246	export interface VoyageRerankConfig {
247	  apiKey?: string;
248	  baseUrl?: string;
249	  /** Injectable for tests; only ever called as (url, init). */
250	  fetchImpl?: (url: string, init: RequestInit) => Promise<Response>;
251	  model?: string;
252	  /**
253	   * Telemetry hook, called once per successful response. The endpoint
254	   * reports tokens, not dollars, so the usage handed here is *computed* from
255	   * `RERANK_COST_PER_MILLION_TOKENS`, and the context this receives always
256	   * has `estimated: true` set — never allowed to fail the rerank call it's
257	   * reporting on, same contract as the gateway's `onUsage`.
258	   */
259	  onUsage?: (usage: GatewayUsage, context?: UsageContext) => void;
260	  /** Documents handed to the cross-encoder. Beyond this the tail is dropped. */
261	  topK?: number;
262	}
263	
264	// MongoDB acquired Voyage AI and now serves the same models from its own
265	// endpoint, authenticated with an Atlas *model* API key rather than a
266	// voyageai.com key. The wire format is unchanged — same request fields, same
267	// `{ data: [{ index, relevance_score }] }` response, same model names — so
268	// only the host differs. Pointing an Atlas key at api.voyageai.com returns a
269	// 403 that names the mismatch, which is how this was found.
270	const DEFAULT_RERANK_BASE_URL = "https://ai.mongodb.com/v1";
271	// The lite model is the interactive default: the quality gap on short
272	// candidates is small and this sits on the latency-sensitive path.
273	const DEFAULT_RERANK_MODEL = "rerank-2.5-lite";
274	const DEFAULT_TOP_K = 50;
275	const TOKENS_PER_MILLION = 1_000_000;
276	
277	/**
278	 * MongoDB's rerank endpoint returns `{"usage":{"total_tokens":N}}` — tokens
279	 * only, no cost, unlike the AI Gateway (which returns dollars directly). So
280	 * this is the one figure in the system computed from a rate constant rather
281	 * than reported by the vendor, and rows derived from it are flagged
282	 * `estimated: true` so an estimate can never be mistaken for an exact figure.
283	 *
284	 * Rate for rerank-2.5-lite, checked 2026-08-04: $0.02 / 1M tokens. Re-check
285	 * when MongoDB reprices — nothing here will notice on its own.
286	 */
287	export const RERANK_COST_PER_MILLION_TOKENS = 0.02;
288	
289	/**
290	 * Cross-encoder reranking over the fused candidate set.
291	 *
292	 * Deliberately the API rather than the `$rerank` aggregation stage: a stage is
293	 * bound to one collection, whereas this takes an arbitrary list and can
294	 * therefore rank facts and raw source excerpts against each other — which
295	 * matters, because a facts-only read path measurably loses recall.
296	 *
297	 * Errors propagate. A reranker that silently falls back to fusion order turns
298	 * a broken dependency into a quiet quality regression.
299	 */
300	export const createVoyageRerank = <T extends RerankableDocument>(
301	  config: VoyageRerankConfig = {}
302	): ((
303	  query: string,
304	  documents: T[],
305	  context?: UsageContext
306	) => Promise<RerankedDocument<T>[]>) => {
307	  const apiKey = config.apiKey ?? process.env.VOYAGE_API_KEY;
308	  if (!apiKey) {
309	    throw new Error(
310	      "VOYAGE_API_KEY is required (pass config.apiKey or set the env var)"
311	    );
312	  }
313	  const baseUrl = config.baseUrl ?? DEFAULT_RERANK_BASE_URL;
314	  const doFetch = config.fetchImpl ?? fetch;
315	  const model = config.model ?? DEFAULT_RERANK_MODEL;
316	  const { onUsage } = config;
317	  const topK = config.topK ?? DEFAULT_TOP_K;
318	
319	  return async (query, documents, context?: UsageContext) => {
320	    if (documents.length === 0) {
321	      return [];
322	    }
323	    const candidates = documents.slice(0, topK);
324	    const res = await doFetch(`${baseUrl}/rerank`, {
325	      body: JSON.stringify({
326	        documents: candidates.map((candidate) => candidate.text),
327	        model,
328	        query,
329	      }),
330	      headers: {
331	        authorization: `Bearer ${apiKey}`,
332	        "content-type": "application/json",
333	      },
334	      method: "POST",
335	    });
336	    if (!res.ok) {
337	      const body = await res.text();
338	      throw new Error(`rerank ${res.status}: ${body.slice(0, 500)}`);
339	    }
340	    const data = (await res.json()) as {
341	      data?: { index: number; relevance_score: number }[];
342	      usage?: { total_tokens?: number };
343	    };
344	
345	    const ranked: RerankedDocument<T>[] = [];
346	    for (const entry of data.data ?? []) {
347	      const document = candidates[entry.index];
348	      // The service echoes positions from the list it was sent; a position
349	      // outside it means the response does not describe this request, and
350	      // emitting undefined downstream would be worse than dropping it.
351	      if (document) {
352	        ranked.push({ document, relevanceScore: entry.relevance_score });
353	      }
354	    }
355	
356	    if (onUsage) {
357	      const totalTokens = data.usage?.total_tokens ?? 0;
358	      const cost =
359	        (totalTokens / TOKENS_PER_MILLION) * RERANK_COST_PER_MILLION_TOKENS;
360	      const usage: GatewayUsage = {
361	        cachedTokens: 0,
362	        completionTokens: 0,
363	        // Rerank has no surcharge — the estimated figure IS the inference
364	        // cost. gatewayCost === inferenceCost + surchargeCost must hold for
365	        // every row this system writes, from any source; setting
366	        // surchargeCost to `cost` here would fabricate a surcharge that was
367	        // never charged and double the true figure once gatewayCost is
368	        // summed against it.
369	        gatewayCost: cost,
370	        inferenceCost: cost,
371	        model,
372	        promptTokens: totalTokens,
373	        reasoningTokens: 0,
374	        surchargeCost: 0,
375	      };
376	      // Telemetry must never fail the rerank call it's reporting on — same
377	      // contract as the gateway's onUsage.
378	      try {
379	        onUsage(usage, context ? { ...context, estimated: true } : undefined);
380	      } catch {
381	        // swallowed deliberately
382	      }
383	    }
384	
385	    return ranked;
386	  };
387	};
388

