1	import { createHash } from "node:crypto";
2	import type { Db } from "mongodb";
3	import { ObjectId } from "mongodb";
4	import { z } from "zod";
5	import {
6	  anchorFilter,
7	  anchorNameFor,
8	  findCandidateAnchors,
9	  unionAnchors,
10	} from "./anchors";
11	import { getCollections } from "./collections";
12	import type { DossierAnchor } from "./dossier";
13	import type { UsageContext } from "./gateway";
14	import { deterministicId, insertIgnoringDuplicate } from "./idempotency";
15	import {
16	  extractLastValidObject,
17	  REFUSAL_REGEX,
18	  stripFences,
19	} from "./llm-reply";
20	import type { Fact, FactAnchors } from "./schemas/facts";
21	import { currentlyValidFilter, factCategoryValues } from "./schemas/facts";
22	import { proposalSchema } from "./schemas/proposals";
23	
24	// Consolidation only proposes merges that reduce redundancy with zero
25	// information loss, so contradictory facts — neither redundant nor mergeable
26	// under those rules — are invisible to it. Extraction only sees a recency
27	// window of the tenant's facts, so a contradiction between two sources
28	// captured months apart is never detected by anything.
29	//
30	// This sweep closes that gap. Candidates are scoped to one anchor and one
31	// category, which is the pairing constraint that keeps the comparison
32	// tractable, and every resolution goes through the same review gate as
33	// everything else: nothing here writes knowledge directly.
34	
35	export interface ContradictionFact {
36	  category: string;
37	  id: string;
38	  text: string;
39	  validFrom?: Date;
40	}
41	
42	const hexObjectId = z.string().regex(/^[0-9a-f]{24}$/);
43	
44	export const llmResolutionSchema = z.object({
45	  category: z.enum(factCategoryValues),
46	  confidence: z.number().min(0).max(1),
47	  // A resolution always replaces both sides of the contradiction it settles.
48	  supersedes: z.array(hexObjectId).min(2),
49	  text: z.string().min(1),
50	});
51	export type LlmResolution = z.infer<typeof llmResolutionSchema>;
52	
53	export const llmContradictionSchema = z.union([
54	  z.strictObject({
55	    reason: z.string().default(""),
56	    skip: z.literal(true),
57	  }),
58	  z.strictObject({
59	    resolutions: z.array(llmResolutionSchema),
60	  }),
61	]);
62	
63	export type ParsedContradiction =
64	  | { kind: "failure"; reason: string }
65	  | { kind: "resolutions"; resolutions: LlmResolution[] }
66	  | { kind: "skip"; reason: string };
67	
68	const isoDay = (date: Date | undefined) =>
69	  date ? date.toISOString().slice(0, 10) : "unknown";
70	
71	export const buildContradictionPrompt = ({
72	  anchorName,
73	  facts,
74	}: {
75	  anchorName: string;
76	  facts: ContradictionFact[];
77	}): string => {
78	  const factLines = facts
79	    .map(
80	      (fact) =>
81	        `${fact.id} | ${fact.category} | since ${isoDay(fact.validFrom)} | ${fact.text}`
82	    )
83	    .join("\n");
84	
85	  return `You audit a company knowledge base for contradictions. Below are the currently valid facts about "${anchorName}". Every fact here is believed to be true right now, so any pair that cannot both be true is a problem a reviewer must settle.
86	
87	Facts (id | category | since | text):
88	${factLines}
89	
90	Return ONLY JSON, no markdown fences, in exactly one of these two shapes:
91	
92	1. Contradictions found:
93	{"resolutions": [{"text": "<the statement that is true now, one self-contained sentence in the facts' language>", "category": "...", "confidence": 0.0-1.0, "supersedes": ["<fact id>", "<fact id>"]}]}
94	
95	2. No contradictions:
96	{"skip": true, "reason": "..."}
97	
98	Rules:
99	- Two facts contradict only if they cannot both be true of the same subject at the same time. Different subjects, different time periods, or different aspects are NOT contradictions.
100	- A change over time is a contradiction worth resolving: prefer the statement supported by the most recent "since" date, and say so in the resolved text.
101	- Facts that merely differ in detail, or that add information, are NOT contradictions — leave them alone.
102	- A resolution must supersede at least TWO of the facts above, and only ids from the list may appear.
103	- No fact id may appear in more than one resolution.
104	- Do not invent information. The resolved text must be supported by the facts it supersedes.
105	- Categories: ${factCategoryValues.join(" | ")}.`;
106	};
107	
108	export const parseContradictionResponse = (
109	  raw: string
110	): ParsedContradiction => {
111	  const text = stripFences(raw);
112	  if (REFUSAL_REGEX.test(text)) {
113	    return { kind: "failure", reason: `model refused: ${text.slice(0, 200)}` };
114	  }
115	  const data = extractLastValidObject(text, llmContradictionSchema);
116	  if (data === undefined) {
117	    return {
118	      kind: "failure",
119	      reason: `no schema-valid JSON object in reply: ${text.slice(0, 200)}`,
120	    };
121	  }
122	  if ("skip" in data) {
123	    return { kind: "skip", reason: data.reason };
124	  }
125	  if (data.resolutions.length === 0) {
126	    return { kind: "skip", reason: "no contradictions found" };
127	  }
128	  return { kind: "resolutions", resolutions: data.resolutions };
129	};
130	
131	// Same contract as consolidation's validateMerges: the model may only claim
132	// ids it was shown, each at most once.
133	const validateResolutions = (
134	  resolutions: LlmResolution[],
135	  shownIds: Set<string>
136	): string | null => {
137	  const claimed = new Set<string>();
138	  for (const [index, resolution] of resolutions.entries()) {
139	    for (const id of resolution.supersedes) {
140	      if (!shownIds.has(id)) {
141	        return `resolutions[${index}] supersedes unknown fact id ${id}`;
142	      }
143	      if (claimed.has(id)) {
144	        return `resolutions[${index}] supersedes fact ${id}, which another resolution already claims`;
145	      }
146	      claimed.add(id);
147	    }
148	  }
149	  return null;
150	};
151	
152	export interface RunContradictionCheckOptions {
153	  anchor: DossierAnchor;
154	  generate: (prompt: string, context?: UsageContext) => Promise<string>;
155	  /** Facts an anchor needs before a check is worth an LLM call. Default 2. */
156	  minFacts?: number;
157	}
158	
159	export interface ContradictionRunResult {
160	  proposalId?: ObjectId;
161	  reason?: string;
162	  status: "failure" | "proposed" | "skipped";
163	}
164	
165	const DEFAULT_MIN_FACTS = 2;
166	
167	export const runContradictionCheck = async (
168	  db: Db,
169	  tenantId: string,
170	  {
171	    anchor,
172	    generate,
173	    minFacts = DEFAULT_MIN_FACTS,
174	  }: RunContradictionCheckOptions
175	): Promise<ContradictionRunResult> => {
176	  const collections = getCollections(db);
177	  const { facts, proposals } = collections;
178	
179	  const validFacts = await facts
180	    .find({ tenantId, ...anchorFilter(anchor), ...currentlyValidFilter })
181	    .sort({ updatedAt: -1 })
182	    .toArray();
183	  if (validFacts.length < minFacts) {
184	    return {
185	      reason: `${validFacts.length} facts < minFacts ${minFacts}`,
186	      status: "skipped",
187	    };
188	  }
189	
190	  // One proposal per (anchor, exact fact set), like consolidation: re-runs are
191	  // idempotent, and a reviewer's "no" is remembered until the facts change.
192	  const factSetHash = createHash("md5")
193	    .update(
194	      validFacts
195	        .map((fact) => fact._id.toHexString())
196	        .sort((a, b) => a.localeCompare(b))
197	        .join(",")
198	    )
199	    .digest("hex");
200	  const proposalId = deterministicId(
201	    `${tenantId}:contradiction:${anchor.kind}:${anchor.id.toHexString()}:${factSetHash}`
202	  );
203	  const existing = await proposals.findOne({ _id: proposalId, tenantId });
204	  if (existing) {
205	    return existing.status === "open"
206	      ? { proposalId, status: "proposed" }
207	      : { reason: "this fact set was already reviewed", status: "skipped" };
208	  }
209	  const openForAnchor = await proposals.findOne({
210	    factDrafts: {
211	      $elemMatch: { [`anchors.${anchor.kind}Id`]: anchor.id },
212	    },
213	    kind: "contradiction",
214	    status: "open",
215	    tenantId,
216	  });
217	  if (openForAnchor) {
218	    return {
219	      reason: `open contradiction proposal ${openForAnchor._id.toHexString()} already covers this anchor`,
220	      status: "skipped",
221	    };
222	  }
223	
224	  const anchorName = await anchorNameFor(collections, tenantId, anchor);
225	  const prompt = buildContradictionPrompt({
226	    anchorName,
227	    facts: validFacts.map((fact) => ({
228	      category: fact.category,
229	      id: fact._id.toHexString(),
230	      text: fact.text,
231	      validFrom: fact.validFrom,
232	    })),
233	  });
234	
235	  let parsed: ParsedContradiction;
236	  try {
237	    parsed = parseContradictionResponse(
238	      await generate(prompt, {
239	        correlationId: anchor.id.toHexString(),
240	        operation: "contradiction",
241	        tenantId,
242	      })
243	    );
244	  } catch (error) {
245	    parsed = {
246	      kind: "failure",
247	      reason: `generate failed: ${error instanceof Error ? error.message : String(error)}`,
248	    };
249	  }
250	  if (parsed.kind === "resolutions") {
251	    const problem = validateResolutions(
252	      parsed.resolutions,
253	      new Set(validFacts.map((fact) => fact._id.toHexString()))
254	    );
255	    if (problem) {
256	      parsed = { kind: "failure", reason: problem };
257	    }
258	  }
259	  if (parsed.kind === "skip") {
260	    return { reason: parsed.reason, status: "skipped" };
261	  }
262	  if (parsed.kind === "failure") {
263	    return { reason: parsed.reason, status: "failure" };
264	  }
265	
266	  const factsById = new Map(
267	    validFacts.map((fact) => [fact._id.toHexString(), fact])
268	  );
269	  const factDrafts: {
270	    anchors: FactAnchors;
271	    category: string;
272	    confidence: number;
273	    supersedes: ObjectId[];
274	    text: string;
275	  }[] = [];
276	  for (const [index, resolution] of parsed.resolutions.entries()) {
277	    const parents = resolution.supersedes
278	      .map((hex) => factsById.get(hex))
279	      .filter((fact): fact is Fact => Boolean(fact));
280	    const resolved = unionAnchors(anchor, parents);
281	    if ("conflict" in resolved) {
282	      return {
283	        reason: `resolutions[${index}] ${resolved.conflict}`,
284	        status: "failure",
285	      };
286	    }
287	    factDrafts.push({
288	      anchors: resolved.anchors,
289	      category: resolution.category,
290	      confidence: resolution.confidence,
291	      supersedes: resolution.supersedes.map((hex) => new ObjectId(hex)),
292	      text: resolution.text,
293	    });
294	  }
295	
296	  const writtenAt = new Date();
297	  const doc = proposalSchema.parse({
298	    _id: proposalId,
299	    createdAt: writtenAt,
300	    entityDrafts: [],
301	    factDrafts,
302	    kind: "contradiction",
303	    status: "open",
304	    tenantId,
305	    updatedAt: writtenAt,
306	  });
307	  await insertIgnoringDuplicate(proposals, doc);
308	  return { proposalId, status: "proposed" };
309	};
310	
311	export interface ContradictionSweepOptions {
312	  generate: (prompt: string, context?: UsageContext) => Promise<string>;
313	  /** Max candidate anchors per sweep. Default 10. */
314	  limit?: number;
315	  minFacts?: number;
316	}
317	
318	export interface ContradictionSweepReport {
319	  failures: string[];
320	  proposed: number;
321	  skipped: number;
322	}
323	
324	export const sweepContradictions = async (
325	  db: Db,
326	  {
327	    generate,
328	    limit = 10,
329	    minFacts = DEFAULT_MIN_FACTS,
330	  }: ContradictionSweepOptions
331	): Promise<ContradictionSweepReport> => {
332	  const report: ContradictionSweepReport = {
333	    failures: [],
334	    proposed: 0,
335	    skipped: 0,
336	  };
337	  const candidates = await findCandidateAnchors(db, { limit, minFacts });
338	
339	  for (const candidate of candidates) {
340	    try {
341	      // biome-ignore lint/performance/noAwaitInLoops: sequential keeps LLM concurrency predictable
342	      const result = await runContradictionCheck(db, candidate.tenantId, {
343	        anchor: candidate.anchor,
344	        generate,
345	        minFacts,
346	      });
347	      if (result.status === "proposed") {
348	        report.proposed += 1;
349	      } else if (result.status === "skipped") {
350	        report.skipped += 1;
351	      } else {
352	        report.failures.push(
353	          `${candidate.anchor.kind} ${candidate.anchor.id.toHexString()}: ${result.reason ?? "failure"}`
354	        );
355	      }
356	    } catch (error) {
357	      report.failures.push(
358	        `${candidate.anchor.kind} ${candidate.anchor.id.toHexString()}: ${error instanceof Error ? error.message : String(error)}`
359	      );
360	    }
361	  }
362	
363	  return report;
364	};
