  test("a long excerpt is truncated with an ellipsis", () => {
    const receipt = composeReceipt({
      contested: false,
      nameOf,
      now: NOW,
      source: makeSource({ excerpt: "x".repeat(400) }),
    });
    expect(receipt.quote).toHaveLength(281);
    expect(receipt.quote?.endsWith("…")).toBe(true);
